      beijing = 1354,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "In the morning, when I woke up, there'd be a little present, and under the moonlight, he'd tell me to cover my eyes and then slip me a kiss.",
