    },
    [8] = {
      beijing = 1354,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "Even hotter than the height of summer, like a burning flame and the seaside wind. Like an exuberant, passionate youth that you can only find in storybooks.",
