      bganim = 0,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "As dusk settled in, the sun was kissing the sand and the water, leaving its rich brush strokes over the landscape like a fine oil painting.",
