    [19] = {
      beijing = 2132,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "Like a yellowed old photograph or an out-of-focus slow-motion shot, the world seemed to have this little corner of it carved out just for us.",
